class Solution { private fun gcd(aValue:Long,bValue:Long):Long{var a=aValue;var b=bValue;while(b!=0L){val remainder=a%b;a=b;b=remainder};return a}fun subarrayLCM(nums:IntArray,k:Int):Int{var answer=0;for(left in nums.indices){var lcm=1L;for(right in left..nums.lastIndex){lcm=lcm/gcd(lcm,nums[right].toLong())*nums[right];if(lcm>k||k.toLong()%lcm!=0L)break;if(lcm==k.toLong())answer++}};return answer} }
